extern "C" unsigned int strlen(const char *);

class string_buf
{
    friend class stringx;
    friend stringx operator+(const stringx &, const stringx &);
    friend stringx operator+(const char *, const stringx &);
    friend stringx operator+(const stringx &, const char *);

    unsigned long long *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx
{
protected:
    char *chars;
    string_buf *my_buf;

public:
    stringx();
    stringx(const stringx &);
    stringx(const char *, int len = -1);
    ~stringx();

    void append(const char *, int len = -1);
    void append(const stringx &);
    void make_room(int);

    friend stringx operator+(const char *, const stringx &);
    friend stringx operator+(const stringx &, const char *);
};

inline stringx operator+(const char *lhs, const stringx &rhs)
{
    stringx foo;
    int len = strlen(lhs);
    foo.make_room(len + rhs.my_buf->char_length);
    foo.append(lhs, len);
    foo.append(rhs);
    return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx foo;
    int len = strlen(rhs);
    foo.make_room(len + lhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs, len);
    return foo;
}

bool file_finder_exists(const stringx &, const stringx &, stringx *found_name = 0);

class SurferFrontEnd
{
    char padding0[0x168];
